{"content":"#!/usr/bin/env python3
"""Deterministic nonogram solver.

Reads puzzle from /app/puzzle.txt (or CLI override) and writes solution
to /app/solution.txt.

Puzzle format:
  ROWS: <int>
  COLS: <int>
  ROW_CLUES:
  <ROWS lines of space-separated ints>
  COL_CLUES:
  <COLS lines of space-separated ints>

Empty line or `0` means no filled cells in that line.
Solution: ROWS lines of COLS chars ('#' filled, '.' empty),
or single line "NO SOLUTION" if unsatisfiable.
"""
import sys
import os


def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)


def parse_int_field(line, name):
    """Extract single integer from a line like 'ROWS: 5' or 'ROWS 5'."""
    # Remove keyword prefix
    upper = line.strip()
    # Find keyword
    # line is known to start with name (case-insensitive)
    rest = upper[len(name):].strip()
    # strip leading ':' or '=' if present
    if rest.startswith(":") or rest.startswith("="):
        rest = rest[1:].strip()
    # Handle 'ROWS: 5' -> rest='5'; 'ROWS' alone -> rest=''
    if not rest:
        raise ValueError(f"Missing value for {name} in line: {line.strip()!r}")
    parts = rest.split()
    if len(parts) != 1:
        raise ValueError(f"Malformed {name} line (expected single integer): {line.strip()!r}")
    try:
        val = int(parts[0])
    except ValueError:
        raise ValueError(f"Malformed {name} value (not an integer): {line.strip()!r}")
    return val


def parse_clue_line(raw_line, line_no_info=""):
    """Parse one clue line into normalized list.

    Returns [] for empty (no blocks), else list of positive ints.
    Raises ValueError on malformed.
    """
    s = raw_line.strip()
    if s == "":
        return []
    # allow commas as separators as well
    s = s.replace(",", " ")
    tokens = s.split()
    nums = []
    for tok in tokens:
        try:
            v = int(tok)
        except ValueError:
            raise ValueError(f"Malformed clue {raw_line!r}{line_no_info}: token {tok!r} is not an integer")
        nums.append(v)
    if len(nums) == 1 and nums[0] == 0:
        return []
    for v in nums:
        if v <= 0:
            raise ValueError(
                f"Malformed clue {raw_line!r}{line_no_info}: block sizes must be positive integers (or single 0 for empty)"
            )
    return nums


def parse_puzzle(path):
    """Parse puzzle file. Returns (rows, cols, row_clues, col_clues).

    row_clues/col_clues are lists of normalized clues ([] = empty).
