            if idx_col_clues is not None:
                raise ValueError("Duplicate COL_CLUES section")
            idx_col_clues = idx
        elif up == "ROWS" or up.startswith("ROWS:") or up.startswith("ROWS ") or up.startswith("ROWS=") or up.startswith("ROWS\t"):
            if idx_rows is not None:
                raise ValueError("Duplicate ROWS section")
            idx_rows = idx
        elif up == "COLS" or up.startswith("COLS:") or up.startswith("COLS ") or up.startswith("COLS=") or up.startswith("COLS\t"):
            if idx_cols is not None:
                raise ValueError("Duplicate COLS section")
            idx_cols = idx
