        # also bare "ROW_CLUES:" exactly -> up == "ROW_CLUES:" startswith true

    # Also handle exact "ROW_CLUES:" / "COL_CLUES:" which upper is e.g. "ROW_CLUES:"
    # already covered by startswith.

    if idx_rows is None:
        raise ValueError("Malformed puzzle: missing ROWS definition")
    if idx_cols is None:
        raise ValueError("Malformed puzzle: missing COLS definition")
    if idx_row_clues is None:
        raise ValueError("Malformed puzzle: missing ROW_CLUES section")
    if idx_col_clues is None:
        raise ValueError("Malformed puzzle: missing COL_CLUES section")

