    if n_cols <= 0:
        raise ValueError(f"Malformed puzzle: COLS must be a positive integer, got {n_cols}")

    # Extract clue blocks between markers.
    # Row block: lines strictly between ROW_CLUES and COL_CLUES if ROW_CLUES comes before COL_CLUES,
    # else lines between ROW_CLUES and end (or next marker). Handle either order.
    # General: row block = lines after ROW_CLUES up to next marker (ROWS/COLS/ROW_CLUES/COL_CLUES) or EOF.
    # Same for col block.
    marker_indices = sorted([
        (idx_rows, "ROWS"),
        (idx_cols, "COLS"),
        (idx_row_clues, "ROW_CLUES"),
        (idx_col_clues, "COL_CLUES"),
    ])

