        # Only trim if there are MORE lines than expected.
        # First attempt: filter out lines that are purely empty AND treat "0" as the empty representation?
        # We try in order:
        # 1. raw == expected -> raw
        # 2. block with all empty lines removed == expected -> use non-empty lines (blanks were separators)
        #    (only if every clue in filtered is non-empty, i.e., empties represented by 0)
        # 3. otherwise malformed.
        filtered = [ln for ln in block if ln.strip() != ""]
        if len(filtered) == expected and len(block) != expected:
            # Ensure no legit blank-clue would be lost: this path assumes blanks were separators.
            # Accept it.
            return filtered
        # Also handle case where block has extra trailing blank due to EOF newline handling:
        # e.g., expected 3 but got 4 with last blank -> could be trailing newline artifact.
        # If len(block) == expected + 1 and block[-1].strip() == "" and filtered == expected lines?
        # covered by case 2.
        raise ValueError(
            f"Malformed puzzle: {name} section expected {expected} clue line(s), found {len(block)} line(s)"
        )

    try:
        row_lines = select_clue_lines(row_block, n_rows, "ROW_CLUES")
    except ValueError as e:
        raise ValueError(str(e))
    try:
        col_lines = select_clue_lines(col_block, n_cols, "COL_CLUES")
    except ValueError as e:
        raise ValueError(str(e))

    row_clues = []
